ctx.restore();}
function enemyPoint(e){const n=Math.min(Math.floor(e.progress),path.length-2),t=e.progress-n,[ax,ay]=path[n],[bx,by]=path[n+1],a=iso(ax-(COLS-1)/2,ay-(ROWS-1)/2),b=iso(bx-(COLS-1)/2,by-(ROWS-1)/2);return{x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t-3}}
function setToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),1700)}
function refresh(){ui.day.textContent=day;ui.coins.textContent=coins;ui.seeds.textContent=seeds;ui.harvest.textContent=`${harvested} moonbean${harvested===1?'':'s'}`;ui.hp.innerHTML=Array.from({length:5},(_,i)=>`<i class="${i>=health?'off':''}"></i>`).join('');document.querySelectorAll('.tool').forEach(b=>b.classList.toggle('active',b.dataset.tool===tool));
if(mode==='day'){ui.phase.textContent=`Morning · Day ${day}`;ui.headline.textContent=day===1?'A little patch of hope.':'The valley wakes again.';ui.description.textContent='Plant moonbeans, water your crops, and gather a harvest before the shadows arrive.';ui.tag.textContent='☀️ Daytime · Moonroot Farm';ui.weather.textContent=day%3===0?'🌦️ A soft drizzle':'☀️ Clear skies';ui.tools.style.display='grid';ui.primary.className='action';ui.primary.disabled=false;ui.primary.textContent='🌙  Send the sun down';ui.hint.textContent='Tap an empty bed to plant. Water crops, then harvest ripe moonbeans for coins.';ui.wave.textContent='Night watch: ready';ui.secondary.style.display='none'}
else if(mode==='night'){ui.phase.textContent=activeWave?`Night watch · Wave ${wave}`:'Dusk · Build your defenses';ui.headline.textContent=activeWave?'Hold the lantern line!':'The wilds are stirring.';ui.description.textContent=activeWave?'Your watchtowers fire on their own. Place more towers to protect the homestead.':'Place watchtowers beside the stone trail, then start the night watch.';ui.tag.textContent='🌙 Nightfall · 3D Watch';ui.weather.textContent='✨ The wilds are awake';ui.tools.style.display='none';ui.primary.className='action night';ui.primary.disabled=activeWave;ui.primary.textContent=activeWave?'🛡️  Watch in progress':'⚔️  Start night watch';ui.hint.textContent=`Tap a clear bed to build a watchtower · 8 coins. Towers auto-fire in range.`;ui.wave.textContent=activeWave?`Wave ${wave} · ${enemies.length} nearby`:'Build towers · 8 coins each';ui.secondary.style.display='none';ui.progress.style.width=activeWave?`${Math.min(100,(waveSpawned/(4+wave))*100)}%`:'0%'}
else {ui.phase.textContent=mode==='win'?'Lantern keeper · Valley safe':'The lantern has gone dark';ui.headline.textContent=mode==='win'?'A brave little valley.':'The shadows took the farm.';ui.description.textContent=mode==='win'?'You held the line through five nights. Your garden will always have a home here.':'Your lantern needs tending. Start a fresh valley and try a different defense.';ui.tag.textContent=mode==='win'?'🌅 Valley protected':'🌑 Night over';ui.weather.textContent='';ui.tools.style.display='none';ui.primary.className='action';ui.primary.disabled=false;ui.primary.textContent='↻  Start a new valley';ui.hint.textContent='';ui.secondary.style.display='none'}
}
function changeMode(next){mode=next;selected=null;refresh();draw()}
function startNight(){if(mode!=='day')return;changeMode('night');setToast('Dusk falls. Build your watchtowers!')}
let spawnClock=0,waveSpawned=0,waveTotal=0;
function beginWave(){if(mode!=='night'||activeWave)return;activeWave=true;waveSpawned=0;waveTotal=4+wave;spawnClock=.15;refresh();setToast(`Wave ${wave} is on the trail!`)}
function advanceDay(){day++;harvested=0;for(const row of plots)for(const p of row){if(p.crop&&p.water){p.crop=Math.min(2,p.crop+1);p.water=false}}towers.length=0;enemies.length=0;shots.length=0;changeMode('day');setToast('Dawn breaks. Your watered crops have grown!')}
function harvestPlot(p){if(!p.crop)return setToast('Nothing planted here yet.');if(p.crop<2)return setToast('Still growing — water it and wait for dawn.');p.crop=0;p.water=false;harvested++;coins+=4;seeds++;setToast('Moonbean harvested! +4 coins, +1 seed');refresh()}
function workPlot(x,y){const p=plots[y][x];selected={x,y};if(tool==='plant'){if(p.crop)return setToast(p.crop===2?'Ready to harvest!':'That bed is occupied.');if(!seeds)return setToast('No seeds left. Harvest moonbeans for more.');p.crop=1;seeds--;setToast('Moonbean seed planted. Give it a drink!')}
else if(tool==='water'){if(!p.crop)return setToast('Plant a seed here first.');if(p.water)return setToast('Already watered today.');p.water=true;setToast('A good drink for your moonbean.')}
else harvestPlot(p);refresh();draw()}
function isPath(x,y){return path.some(([px,py])=>px===x&&py===y)}
function placeTower(x,y){if(isPath(x,y))return setToast('Keep the stone trail clear.');if(towers.some(t=>t.x===x&&t.y===y))return setToast('A watchtower is already here.');if(coins<8)return setToast('You need 8 coins for a watchtower.');coins-=8;towers.push({x,y,cool:.2});selected={x,y};refresh();draw();setToast('Watchtower built! It will fire at nearby shadows.')}
function hit(e){const r=canvas.getBoundingClientRect(),px=e.clientX-r.left,py=e.clientY-r.top;let best=null,dist=Infinity;for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++){const p=tile(x,y),d=Math.hypot((px-p.x)/dims.tw,(py-p.y)/dims.th);if(d<dist){dist=d;best={x,y}}}if(dist>.56)return;if(mode==='day')workPlot(best.x,best.y);else if(mode==='night')placeTower(best.x,best.y)}
canvas.addEventListener('pointerdown',e=>{e.preventDefault();hit(e)});document.querySelectorAll('.tool').forEach(b=>b.addEventListener('click',()=>{tool=b.dataset.tool;refresh()}));ui.primary.addEventListener('click',()=>{if(mode==='day')startNight();else if(mode==='night'&&!activeWave)beginWave();else if(mode==='win'||mode==='lose')reset()});ui.secondary.addEventListener('click',advanceDay);
function reset(){day=1;coins=12;seeds=6;health=5;harvested=0;wave=1;activeWave=false;towers.length=enemies.length=shots.length=particles.length=0;for(const row of plots)for(const p of row){p.crop=0;p.water=false}tool='plant';changeMode('day');setToast('A fresh start in Moonroot Valley.')}

